CREATE OR REPLACE FUNCTION public.atlas_charge_budget_checked(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_budget public.budgets;
  v_existing public.payments;
  v_new public.payments;
  v_paid numeric(12,2);
  v_amount numeric(12,2);
  v_advance numeric(12,2);
  v_manual_discount numeric(12,2);
  v_assessment_discount numeric(12,2);
  v_manual_adjustment numeric(12,2);
  v_settled numeric(12,2);
  v_invoice_total numeric(12,2);
  v_ref text;
  v_advance_ref text;
begin
  if auth.uid() is null then raise exception 'Se requiere una sesión activa'; end if;
  v_ref := nullif(p_payload->>'client_ref','');
  v_amount := round(coalesce((p_payload->>'amount')::numeric,0),2);
  v_advance := round(coalesce((p_payload->'metadata'->>'advance_amount')::numeric,0),2);
  v_manual_discount := round(coalesce((p_payload->'metadata'->>'manual_discount')::numeric,0),2);
  v_assessment_discount := round(coalesce((p_payload->'metadata'->>'assessment_discount')::numeric,0),2);
  v_manual_adjustment := round(coalesce((p_payload->'metadata'->>'manual_adjustment')::numeric,0),2);
  v_settled := round(v_amount+v_advance+v_manual_discount+v_assessment_discount+v_manual_adjustment,2);
  v_advance_ref := nullif(btrim(p_payload->'metadata'->>'advance_reference'),'');
  if v_ref is null or v_amount<=0 then raise exception 'Referencia o importe de cobro inválido'; end if;
  if least(v_advance,v_manual_discount,v_assessment_discount,v_manual_adjustment)<0 then
    raise exception 'Las señales y descuentos no pueden ser negativos';
  end if;
  if v_advance>0 and v_advance_ref is null then
    raise exception 'Indica la referencia de la señal o anticipo previo';
  end if;
  if v_advance>0 and nullif(btrim(p_payload->'metadata'->>'advance_concept'),'') is null then
    raise exception 'Indica el concepto al que corresponde la señal o anticipo';
  end if;
  if (v_manual_discount>0 or v_manual_adjustment>0)
     and nullif(btrim(p_payload->'metadata'->>'discount_concept'),'') is null then
    raise exception 'Indica el concepto al que corresponde el descuento';
  end if;
  if p_payload->'metadata'->>'kind' <> 'budget' or p_payload->>'status' <> 'completed' then
    raise exception 'Esta operación solo admite cobros de presupuestos';
  end if;
  if abs(coalesce((p_payload->'metadata'->>'settled_amount')::numeric,v_settled)-v_settled)>0.01 then
    raise exception 'El desglose del cobro no coincide con el importe liquidado';
  end if;
  select coalesce(sum(coalesce((line->>'amount')::numeric,0)),0) into v_invoice_total
  from jsonb_array_elements(coalesce(p_payload->'metadata'->'invoice_lines','[]'::jsonb)) line;
  if abs(v_invoice_total-v_amount)>0.01 then
    raise exception 'El desglose de factura no coincide con el importe final cobrado';
  end if;

  select * into v_budget from public.budgets
    where id=(p_payload->>'budget_id')::uuid and organization_id=(p_payload->>'organization_id')::uuid
      and clinic_id=(p_payload->>'clinic_id')::uuid and patient_id=(p_payload->>'patient_id')::uuid
      and deleted_at is null for update;
  if not found then raise exception 'Presupuesto no disponible en esta clínica'; end if;
  if abs(v_budget.total-(p_payload->'metadata'->>'budget_total')::numeric)>0.01 then
    raise exception 'El presupuesto no coincide con la versión central. Recarga la ficha.';
  end if;

  select * into v_existing from public.payments
    where organization_id=v_budget.organization_id and clinic_id=v_budget.clinic_id and client_ref=v_ref;
  if found then
    if v_existing.status<>'completed' or v_existing.cancelled_at is not null then
      raise exception 'Este intento de cobro ya fue anulado. Actualiza la ficha antes de continuar.';
    end if;
    return to_jsonb(v_existing)||jsonb_build_object('already_exists',true);
  end if;

  if v_advance_ref is not null and exists(
    select 1 from public.payments payment
    where payment.organization_id=v_budget.organization_id
      and payment.clinic_id=v_budget.clinic_id
      and payment.status='completed' and payment.cancelled_at is null and payment.deleted_at is null
      and payment.metadata->>'kind'='budget'
      and lower(btrim(payment.metadata->>'advance_reference'))=lower(v_advance_ref)
  ) then
    raise exception 'La señal o anticipo con referencia % ya se utilizó en otro cobro.',v_advance_ref;
  end if;

  select coalesce(sum(coalesce((metadata->>'settled_amount')::numeric,amount)),0) into v_paid
  from public.payments
  where budget_id=v_budget.id and status='completed' and cancelled_at is null and deleted_at is null;
  if v_paid+v_settled>v_budget.total+0.01 then
    raise exception 'Este presupuesto ya tiene % € liquidados. Solo quedan % € pendientes.',v_paid,greatest(0,v_budget.total-v_paid);
  end if;

  insert into public.payments(organization_id,clinic_id,patient_id,budget_id,appointment_id,payment_type,
    amount,method,status,external_reference,notes,paid_at,created_by,client_ref,metadata)
  values(v_budget.organization_id,v_budget.clinic_id,v_budget.patient_id,v_budget.id,
    nullif(p_payload->>'appointment_id','')::uuid,p_payload->>'payment_type',v_amount,
    p_payload->>'method','completed',p_payload->>'external_reference',p_payload->>'notes',
    coalesce((p_payload->>'paid_at')::timestamptz,now()),(p_payload->>'created_by')::uuid,
    v_ref,jsonb_set(coalesce(p_payload->'metadata','{}'::jsonb),'{settled_amount}',to_jsonb(v_settled),true))
  returning * into v_new;
  return to_jsonb(v_new)||jsonb_build_object('already_exists',false);
end;$function$

CREATE OR REPLACE FUNCTION private.atlas_replace_budget_lines(p_budget_id uuid, p_lines jsonb DEFAULT '[]'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org uuid;
  v_user uuid := auth.uid();
  v_line jsonb;
  v_order integer := 0;
begin
  if v_user is null then
    raise exception 'Se requiere una sesión autenticada';
  end if;
  select organization_id into v_org
  from public.budgets
  where id=p_budget_id and deleted_at is null;
  if v_org is null then
    raise exception 'Presupuesto no encontrado';
  end if;
  if not public.has_permission(v_org,'budgets_write') then
    raise exception 'Sin permiso para modificar presupuestos';
  end if;
  if jsonb_typeof(coalesce(p_lines,'[]'::jsonb)) <> 'array' then
    raise exception 'Las líneas del presupuesto deben ser una lista';
  end if;

  delete from public.budget_lines where budget_id=p_budget_id;
  for v_line in select value from jsonb_array_elements(coalesce(p_lines,'[]'::jsonb))
  loop
    v_order := v_order + 1;
    insert into public.budget_lines(
      organization_id,budget_id,service_code,service_name,sessions,
      unit_price,discount,line_order,metadata
    ) values (
      v_org,p_budget_id,nullif(v_line->>'service_code',''),
      coalesce(nullif(btrim(v_line->>'service_name'),''),'Tratamiento'),
      greatest(1,coalesce((v_line->>'sessions')::integer,1)),
      greatest(0,coalesce((v_line->>'unit_price')::numeric,0)),
      greatest(0,least(100,coalesce((v_line->>'discount')::numeric,0))),
      v_order,coalesce(v_line->'metadata','{}'::jsonb)
    );
  end loop;
  return v_order;
end;
$function$

CREATE OR REPLACE FUNCTION public.atlas_upsert_budget(p_patient_id uuid, p_client_ref text, p_budget jsonb, p_lines jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org uuid;
  v_clinic uuid;
  v_user uuid := auth.uid();
  v_budget public.budgets;
  v_saved_lines integer;
begin
  if v_user is null then raise exception 'Se requiere una sesión autenticada'; end if;
  if p_patient_id is null or nullif(btrim(p_client_ref),'') is null then
    raise exception 'Paciente y referencia del presupuesto son obligatorios';
  end if;

  select organization_id,clinic_id into v_org,v_clinic
  from public.patients where id=p_patient_id and deleted_at is null;
  if v_org is null or v_clinic is null then raise exception 'Paciente no encontrado'; end if;
  if not public.has_permission(v_org,'budgets_write') then
    raise exception 'Sin permiso para modificar presupuestos';
  end if;

  insert into public.budgets(
    organization_id,clinic_id,patient_id,client_ref,name,status,discount,total,
    payment_terms,accepted_at,created_by,metadata,deleted_at,updated_at
  ) values (
    v_org,v_clinic,p_patient_id,btrim(p_client_ref),
    coalesce(nullif(btrim(p_budget->>'name'),''),'Presupuesto'),
    coalesce(nullif(p_budget->>'status',''),'draft'),
    greatest(0,least(100,coalesce((p_budget->>'discount')::numeric,0))),
    greatest(0,coalesce((p_budget->>'total')::numeric,0)),
    coalesce(p_budget->'payment_terms','{}'::jsonb),
    case when coalesce(p_budget->>'accepted_at','')='' then null else (p_budget->>'accepted_at')::timestamptz end,
    v_user,coalesce(p_budget->'metadata','{}'::jsonb),null,now()
  )
  on conflict (clinic_id,client_ref) where client_ref is not null
  do update set patient_id=excluded.patient_id,name=excluded.name,status=excluded.status,
    discount=excluded.discount,total=excluded.total,payment_terms=excluded.payment_terms,
    accepted_at=excluded.accepted_at,metadata=excluded.metadata,deleted_at=null,updated_at=now()
  returning * into v_budget;

  v_saved_lines := private.atlas_replace_budget_lines(v_budget.id,p_lines);

  return jsonb_build_object('id',v_budget.id,'budget_number',v_budget.budget_number,
    'client_ref',v_budget.client_ref,'updated_at',v_budget.updated_at,'saved_lines',v_saved_lines);
end;
$function$

CREATE OR REPLACE FUNCTION public.atlas_upsert_budget_checked(p_patient_id uuid, p_client_ref text, p_budget jsonb, p_lines jsonb, p_expected_updated_at timestamp with time zone, p_operation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_clinic uuid;
  v_old public.budgets;
begin
  if auth.uid() is null or nullif(p_operation_id, '') is null then
    raise exception 'Se requiere una sesión y referencia de guardado';
  end if;

  select clinic_id
  into v_clinic
  from public.patients
  where id = p_patient_id
    and deleted_at is null;

  if v_clinic is null then
    raise exception 'Paciente no disponible';
  end if;

  if not pg_try_advisory_xact_lock(hashtextextended(v_clinic::text || ':' || p_client_ref, 0)) then
    raise exception 'Otro guardado de este presupuesto sigue en curso. Vuelve a intentarlo.'
      using errcode = '40001';
  end if;

  select *
  into v_old
  from public.budgets
  where clinic_id = v_clinic
    and client_ref = p_client_ref
  for update;

  if found then
    if v_old.patient_id <> p_patient_id or v_old.deleted_at is not null then
      raise exception 'Presupuesto no disponible';
    end if;
    if v_old.metadata ->> 'last_server_operation' = p_operation_id then
      return jsonb_build_object(
        'id', v_old.id,
        'budget_number', v_old.budget_number,
        'client_ref', v_old.client_ref,
        'updated_at', v_old.updated_at
      );
    end if;
    if p_expected_updated_at is null or v_old.updated_at is distinct from p_expected_updated_at then
      raise exception 'Otro usuario ha actualizado este presupuesto. Revisa la versión del servidor antes de guardar.'
        using errcode = '40001';
    end if;
  end if;

  return public.atlas_upsert_budget(
    p_patient_id,
    p_client_ref,
    jsonb_set(
      p_budget,
      '{metadata}',
      coalesce(p_budget -> 'metadata', '{}'::jsonb)
        || jsonb_build_object('last_server_operation', p_operation_id)
    ),
    p_lines
  );
end;
$function$
